CREATE OR REPLACE FUNCTION public.guard_profile_customer_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF (TG_OP = 'INSERT' AND NEW.customer_id IS NOT NULL) OR (TG_OP = 'UPDATE' AND NEW.customer_id IS DISTINCT FROM OLD.customer_id) THEN IF NOT (coalesce(auth.role(),'') = 'service_role' OR (auth.uid() IS NOT NULL AND coalesce(public.is_master_admin(auth.uid()),false)) OR (auth.uid() IS NULL AND session_user IN ('postgres','supabase_admin'))) THEN RAISE EXCEPTION 'Only administrators can link client accounts'; END IF; END IF; RETURN NEW; END $$;
ALTER POLICY "portal create own tickets" ON public.tickets WITH CHECK (customer_id = public.portal_customer_id(auth.uid()) AND created_by = auth.uid() AND status = 'open' AND assigned_to IS NULL AND assigned_team IS NULL AND archived_at IS NULL AND account_number = (SELECT c.account_number FROM public.customers c WHERE c.id = customer_id));